import {useState} from 'react';
import {Alert,Linking,Pressable,StyleSheet,Text,View} from '@/platform/react-native';
import {router,useLocalSearchParams} from '@/router';
import {useMutation,useQuery,useQueryClient} from '@tanstack/react-query';
import {Ionicons} from '@/platform/icons';
import {api} from '@/lib/api';import {Badge,Button,Card,EmptyState,Header,Input,Modal,Muted,Screen,useAppTheme} from '@/components/UI';
import {CountryPhoneField} from '@/components/CountryPhoneField';
type Contact={Id:string;Name:string;Phone:string;ContactType?:string;IsOfficial:boolean};type EmergencyAlert={Id:string;Title:string;Message:string;Severity:string;AlertType?:string;AffectedArea?:string;Active:boolean;CreatedAt:string;MyResponse?:string;ResolutionNote?:string};
export default function Emergency(){const{id}=useLocalSearchParams<{id:string}>();const{palette}=useAppTheme();const qc=useQueryClient();const[sosOpen,setSosOpen]=useState(false),[alertOpen,setAlertOpen]=useState(false),[contactOpen,setContactOpen]=useState(false),[sosMessage,setSosMessage]=useState(''),[sosArea,setSosArea]=useState(''),[title,setTitle]=useState(''),[message,setMessage]=useState(''),[area,setArea]=useState(''),[severity,setSeverity]=useState<'INFO'|'NOTICE'|'WARNING'|'HIGH'|'CRITICAL'>('HIGH'),[contactName,setContactName]=useState(''),[contactPhone,setContactPhone]=useState(''),[contactType,setContactType]=useState('Emergency contact');
 const caps=useQuery<any>({queryKey:['capabilities',id],queryFn:async()=>(await api.get(`/communities/${id}/capabilities`)).data});const data=useQuery<any>({queryKey:['emergency-dashboard',id],queryFn:async()=>(await api.get(`/communities/${id}/emergency/dashboard`)).data});const permissions=caps.data?.permissions||[],canSend=permissions.includes('EMERGENCY_SEND'),canManage=permissions.includes('EMERGENCY_MANAGE');const alerts:EmergencyAlert[]=data.data?.alerts||[],active=alerts.find(x=>x.Active),contacts:Contact[]=data.data?.contacts||[];
 const sos=useMutation({mutationFn:()=>api.post(`/communities/${id}/sos`,{message:sosMessage.trim()||undefined,approximateArea:sosArea.trim()||undefined}),onSuccess:()=>{setSosOpen(false);setSosMessage('');setSosArea('');Alert.alert('Community SOS sent','Authorised community emergency coordinators have been notified. Contact official emergency services directly if there is immediate danger.')},onError:(e:any)=>Alert.alert('Unable to send SOS',e.response?.data?.message||e.message)});
 const create=useMutation({mutationFn:()=>api.post(`/communities/${id}/alerts`,{title:title.trim(),message:message.trim(),alertType:'COMMUNITY_EMERGENCY',severity,requiresAcknowledgement:true,affectedArea:area.trim()||undefined}),onSuccess:()=>{setAlertOpen(false);setTitle('');setMessage('');setArea('');qc.invalidateQueries({queryKey:['emergency-dashboard',id]});qc.invalidateQueries({queryKey:['alerts',id]});Alert.alert('Emergency alert queued','The emergency broadcast has been queued for community members.')},onError:(e:any)=>Alert.alert('Unable to send alert',e.response?.data?.message||e.message)});
 const respond=useMutation({mutationFn:(response:'SAFE'|'NEED_HELP')=>api.post(`/alerts/${active!.Id}/respond`,{response}),onSuccess:()=>{qc.invalidateQueries({queryKey:['emergency-dashboard',id]});Alert.alert('Safety status shared','Your response has been recorded for the active alert.')},onError:(e:any)=>Alert.alert('Unable to share status',e.response?.data?.message||e.message)});
 const addContact=useMutation({mutationFn:()=>api.post(`/communities/${id}/emergency-contacts`,{name:contactName.trim(),phone:contactPhone.trim(),contactType:contactType.trim()||undefined,isOfficial:false}),onSuccess:()=>{setContactOpen(false);setContactName('');setContactPhone('');qc.invalidateQueries({queryKey:['emergency-dashboard',id]})}});
 function contact(kind:string){return contacts.find(c=>`${c.ContactType||''} ${c.Name}`.toLowerCase().includes(kind))}function call(c?:Contact){if(c?.Phone)Linking.openURL(`tel:${c.Phone}`);else Alert.alert('Contact not configured','A community administrator must add and verify this emergency contact before it can be called from CDA Connect.')}function detail(a:EmergencyAlert){Alert.alert(a.Title,`${a.Message}${a.AffectedArea?`\n\nAffected area: ${a.AffectedArea}`:''}${a.ResolutionNote?`\n\nResolution: ${a.ResolutionNote}`:''}`)}
 const official=contacts.find(c=>c.IsOfficial),police=contact('police'),ambulance=contact('ambulance')||contact('hospital');
 return <Screen scroll contentStyle={s.page}>
 <View style={[s.hero,{backgroundColor:palette.dangerSoft,borderColor:palette.danger}]}><View style={s.heroInfo}><View style={s.dangerCircle}><Ionicons name="shield" size={28} color={palette.danger}/></View><View style={{flex:1}}><Text style={[s.heroTitle,{color:palette.danger}]}>In an emergency?</Text><Muted>Get help, alert your community and stay safe. CDA Connect does not replace official emergency services.</Muted></View></View><View style={s.heroActions}><EmergencyAction icon="notifications-outline" label="Send Emergency Alert" filled color={palette.danger} onPress={()=>canSend?setAlertOpen(true):Alert.alert('Permission required','Only authorised emergency administrators can broadcast an alert. You can still send a Community SOS.')}/><EmergencyAction icon="call" label="SOS" color={palette.danger} onPress={()=>setSosOpen(true)}/></View></View>
 <Text style={[s.sectionTitle,{color:palette.text}]}>Quick Actions</Text><View style={s.quickGrid}><Quick icon="call" title="Official Emergency" value={official?.Phone||'Not configured'} color={palette.danger} onPress={()=>call(official)}/><Quick icon="shield" title="Call Police" value={police?.Phone||'Not configured'} color="#1683E8" onPress={()=>call(police)}/><Quick icon="medkit" title="Call Ambulance" value={ambulance?.Phone||'Not configured'} color={palette.success} onPress={()=>call(ambulance)}/><Quick icon="alert-circle" title="Community SOS" value="Alert coordinators" color="#7C3AED" onPress={()=>setSosOpen(true)}/></View>
 <View style={[s.safety,{backgroundColor:'#EFF6FF',borderColor:'#93C5FD'}]}><View style={s.safeCircle}><Ionicons name="shield-checkmark" size={43} color="#1683E8"/></View><View style={{flex:1}}><Text style={[s.heroTitle,{color:'#1683E8'}]}>Safety Check</Text><Muted>{active?'Share your status for the active community alert.':'Safety check becomes available whenever an active alert requires acknowledgement.'}</Muted></View><Button title={active?.MyResponse==='SAFE'?"Status: Safe":"I'm Safe"} variant="secondary" disabled={!active||respond.isPending} onPress={()=>respond.mutate('SAFE')}/>{active?<Button title="Need Help" variant="danger" disabled={respond.isPending} onPress={()=>respond.mutate('NEED_HELP')}/>:null}</View>
 <View style={s.sectionHead}><Text style={[s.sectionTitle,{color:palette.text}]}>Recent Alerts</Text><Pressable onPress={()=>data.refetch()}><Text style={{color:palette.primary,fontWeight:'800'}}>Refresh</Text></Pressable></View>{alerts.length?<Card style={s.list}>{alerts.slice(0,6).map(a=><Pressable key={a.Id} onPress={()=>detail(a)} style={[s.alertRow,{borderBottomColor:palette.border}]}><View style={[s.rowIcon,{backgroundColor:a.Active?palette.dangerSoft:palette.successSoft}]}><Ionicons name={a.Active?'warning':'shield-checkmark'} size={25} color={a.Active?palette.danger:palette.success}/></View><View style={{flex:1}}><Text style={[s.rowTitle,{color:palette.text}]}>{a.Title}</Text><Muted numberOfLines={1}>{a.Message}</Muted></View><View style={s.alertMeta}><Muted>{new Date(a.CreatedAt).toLocaleDateString()}</Muted><Badge text={a.Active?a.Severity:'ALL CLEAR'} tone={a.Active?'red':'green'}/></View><Ionicons name="chevron-forward" size={19} color={palette.muted}/></Pressable>)}</Card>:<EmptyState icon="shield-checkmark-outline" title="No emergency alerts" body="There are currently no emergency alerts for this community."/>}
 <View style={s.sectionHead}><Text style={[s.sectionTitle,{color:palette.text}]}>Emergency Contacts</Text>{canManage?<Pressable accessibilityRole="button" accessibilityLabel="Add emergency contact" onPress={()=>setContactOpen(true)}><Text style={{color:palette.primary,fontWeight:'800'}}>Add</Text></Pressable>:null}</View>{contacts.length?<Card style={s.list}>{contacts.map(c=><View key={c.Id} style={[s.contactRow,{borderBottomColor:palette.border}]}><View style={[s.rowIcon,{backgroundColor:palette.primarySoft}]}><Ionicons name={String(c.ContactType).toLowerCase().includes('police')?'shield-outline':String(c.ContactType).toLowerCase().includes('hospital')?'medkit-outline':'person-outline'} size={20} color={palette.primary}/></View><View style={{flex:1}}><Text style={[s.rowTitle,{color:palette.text}]}>{c.Name}</Text><Muted>{c.ContactType||'Emergency contact'}{c.IsOfficial?' · Official':''}</Muted></View><Pressable accessibilityRole="button" accessibilityLabel={`Message ${c.Name}`} onPress={()=>Linking.openURL(`sms:${c.Phone}`)} style={[s.contactAction,{backgroundColor:palette.successSoft}]}><Ionicons name="chatbubble-ellipses-outline" size={19} color={palette.success}/></Pressable><Pressable accessibilityRole="button" accessibilityLabel={`Call ${c.Name}`} onPress={()=>call(c)} style={[s.contactAction,{backgroundColor:palette.successSoft}]}><Ionicons name="call" size={19} color={palette.success}/></Pressable></View>)}</Card>:<EmptyState icon="call-outline" title="No emergency contacts configured" body="Community administrators can add verified local contacts instead of relying on sample phone numbers."/>}
 <Pressable onPress={()=>router.push(`/community/${id}/documents` as any)} style={[s.prepared,{backgroundColor:'#FFF7E8',borderColor:'#F7C66B'}]}><Ionicons name="bulb-outline" size={36} color={palette.warning}/><View style={{flex:1}}><Text style={{color:palette.warning,fontWeight:'900'}}>Stay Prepared</Text><Muted>Review community emergency procedures and important documents.</Muted></View><Ionicons name="chevron-forward" size={23} color={palette.warning}/></Pressable>
 <Modal visible={sosOpen} animationType="slide" presentationStyle="pageSheet" onRequestClose={()=>setSosOpen(false)}><Screen scroll><Header title="Community SOS" right={<Pressable onPress={()=>setSosOpen(false)}><Ionicons name="close" size={26} color={palette.text}/></Pressable>}/><Card style={{backgroundColor:palette.dangerSoft}}><Text style={{color:palette.danger,fontWeight:'900'}}>For immediate danger, call the appropriate official emergency service directly.</Text></Card><Input placeholder="What help do you need?" multiline value={sosMessage} onChangeText={setSosMessage}/><Input placeholder="Approximate area — do not enter a private home address" value={sosArea} onChangeText={setSosArea}/><Button title="Send Community SOS" variant="danger" icon="send" loading={sos.isPending} onPress={()=>sos.mutate()}/></Screen></Modal>
 <Modal visible={alertOpen} animationType="slide" presentationStyle="pageSheet" onRequestClose={()=>setAlertOpen(false)}><Screen scroll><Header title="Send Emergency Alert" right={<Pressable onPress={()=>setAlertOpen(false)}><Ionicons name="close" size={26} color={palette.text}/></Pressable>}/><Muted>Only authorised roles can broadcast alerts. Members will be asked to confirm whether they are safe or need help.</Muted><Input placeholder="Alert title" value={title} onChangeText={setTitle}/><Input placeholder="Instructions and safety information" multiline value={message} onChangeText={setMessage}/><Input placeholder="Affected area" value={area} onChangeText={setArea}/><Text style={[s.label,{color:palette.text}]}>Severity</Text><View style={s.severities}>{(['INFO','NOTICE','WARNING','HIGH','CRITICAL'] as const).map(x=><Pressable key={x} onPress={()=>setSeverity(x)} style={[s.severity,{borderColor:severity===x?palette.danger:palette.border,backgroundColor:severity===x?palette.dangerSoft:palette.surface}]}><Text style={{color:severity===x?palette.danger:palette.text,fontWeight:'800'}}>{x}</Text></Pressable>)}</View><Button title="Broadcast Emergency Alert" variant="danger" loading={create.isPending} disabled={title.trim().length<2||!message.trim()} onPress={()=>create.mutate()}/></Screen></Modal>
 <Modal visible={contactOpen} animationType="slide" presentationStyle="pageSheet" onRequestClose={()=>setContactOpen(false)}><Screen scroll><Header title="Add Emergency Contact" right={<Pressable onPress={()=>setContactOpen(false)}><Ionicons name="close" size={26} color={palette.text}/></Pressable>}/><Input placeholder="Contact name" value={contactName} onChangeText={setContactName}/><CountryPhoneField value={contactPhone} onChange={setContactPhone}/><Input placeholder="Type, e.g. Police, Hospital, Coordinator" value={contactType} onChangeText={setContactType}/><Button title="Add Contact" loading={addContact.isPending} disabled={contactName.trim().length<2||contactPhone.trim().length<7} onPress={()=>addContact.mutate()}/></Screen></Modal>
 </Screen>}
function EmergencyAction({icon,label,color,filled=false,onPress}:{icon:keyof typeof Ionicons.glyphMap;label:string;color:string;filled?:boolean;onPress:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={label} onPress={onPress} style={[s.emergencyAction,{borderColor:color,backgroundColor:filled?color:'transparent'}]}><Ionicons name={icon} size={18} color={filled?'#FFFFFF':color}/><Text numberOfLines={1} adjustsFontSizeToFit style={[s.emergencyActionText,{color:filled?'#FFFFFF':color}]}>{label}</Text></Pressable>}
function Quick({icon,title,value,color,onPress}:{icon:keyof typeof Ionicons.glyphMap;title:string;value:string;color:string;onPress:()=>void}){return <Pressable accessibilityRole="button" accessibilityLabel={`${title}: ${value}`} onPress={onPress} style={s.quick}><View style={[s.quickIcon,{backgroundColor:`${color}18`}]}><Ionicons name={icon} size={24} color={color}/></View><View style={s.quickCopy}><Text style={s.quickTitle}>{title}</Text><Text numberOfLines={1} style={[s.quickValue,{color}]}>{value}</Text></View></Pressable>}
const s=StyleSheet.create({page:{width:'100%',maxWidth:820,alignSelf:'center',paddingBottom:125},hero:{borderWidth:1,borderRadius:16,padding:14,gap:13,marginVertical:8},heroInfo:{flexDirection:'row',gap:12,alignItems:'center'},dangerCircle:{width:52,height:52,borderRadius:26,backgroundColor:'#FFE1E1',alignItems:'center',justifyContent:'center',flexShrink:0},heroTitle:{fontSize:17,fontWeight:'900',marginBottom:3},heroActions:{flexDirection:'row',gap:8},emergencyAction:{height:42,borderWidth:1,borderRadius:12,paddingHorizontal:10,flexDirection:'row',gap:6,alignItems:'center',justifyContent:'center',flex:1,minWidth:0},emergencyActionText:{fontSize:12,fontWeight:'900',textAlign:'center',flexShrink:1},sectionTitle:{fontSize:17,fontWeight:'900',marginTop:15,marginBottom:8},quickGrid:{flexDirection:'row',flexWrap:'wrap',justifyContent:'space-between',rowGap:9},quick:{width:'48.5%',minHeight:84,borderWidth:1,borderColor:'#E2E8F0',borderRadius:14,flexDirection:'row',alignItems:'center',padding:10,gap:9},quickIcon:{width:44,height:44,borderRadius:22,alignItems:'center',justifyContent:'center',flexShrink:0},quickCopy:{flex:1,minWidth:0,gap:3},quickTitle:{fontSize:12,fontWeight:'900'},quickValue:{fontSize:10.5,fontWeight:'800'},safety:{borderWidth:1,borderRadius:16,padding:13,flexDirection:'row',flexWrap:'wrap',gap:10,alignItems:'center',marginTop:16},safeCircle:{width:48,height:48,borderRadius:24,backgroundColor:'#DBEAFE',alignItems:'center',justifyContent:'center'},sectionHead:{flexDirection:'row',alignItems:'center',justifyContent:'space-between'},list:{paddingVertical:0,overflow:'hidden'},alertRow:{minHeight:78,flexDirection:'row',alignItems:'center',gap:8,borderBottomWidth:1},rowIcon:{width:42,height:42,borderRadius:21,alignItems:'center',justifyContent:'center'},rowTitle:{fontSize:14,fontWeight:'900'},alertMeta:{alignItems:'flex-end',gap:4},contactRow:{minHeight:70,flexDirection:'row',alignItems:'center',gap:8,borderBottomWidth:1},contactAction:{width:38,height:38,borderRadius:19,alignItems:'center',justifyContent:'center'},prepared:{borderWidth:1,borderRadius:16,padding:13,marginTop:16,flexDirection:'row',alignItems:'center',gap:11},label:{fontSize:14,fontWeight:'900',marginTop:12},severities:{flexDirection:'row',flexWrap:'wrap',gap:7,marginVertical:10},severity:{borderWidth:1,borderRadius:999,paddingHorizontal:10,paddingVertical:8}})
